<div class="two-col"><section class="card" id="new-asset"><h2>Create an asset</h2><form class="stack" method="post" action="/investments"><?= csrf_field() ?><label>Name<input name="name" placeholder="Your investment name" maxlength="100" required></label><label>Type<select name="type"><?php foreach (InvestmentService::TYPES as $key=>$label): ?><option value="<?= e($key) ?>"><?= e($label) ?></option><?php endforeach; ?></select></label><label>Start date<input name="start_date" type="date" value="<?= e(date('Y-m-d')) ?>" required></label><label>Notes<textarea name="notes" rows="3" maxlength="2000"></textarea></label><button>Create asset</button></form></section>
<section class="card"><h2>Goals worth working toward</h2><?php foreach ($goals as $g): ?><div class="budget-row"><div><strong><?= e($g['title']) ?></strong><span><?= money($g['current']) ?> / <?= money($g['target_amount']) ?></span></div><?= progress_donut((float)$g['pct'],'Goal funding','Progress toward your linked target',true,'green','Funded') ?><small><?= e($g['asset'] ?? 'No linked asset') ?><?= $g['due_date'] ? ' · Due '.e($g['due_date']) : '' ?></small><form method="post" action="/goals/<?= e($g['id']) ?>/delete" data-confirm="Remove this goal?"><?= csrf_field() ?><button class="delete">Remove goal</button></form></div><?php endforeach; ?><?php if (!$goals): ?><p class="muted">Link a goal to an asset to track its progress automatically.</p><?php endif; ?><h3>Add a goal</h3><form class="stack" method="post" action="/goals"><?= csrf_field() ?><label>Goal<input name="title" maxlength="200" placeholder="Your savings goal" required></label><label>Target (Rs.)<input type="number" min="0.01" max="9999999999.99" step="0.01" name="target" required></label><label>Due date (optional)<input type="date" name="due"></label><label>Linked asset<select name="asset_id"><option value="">No linked asset</option><?php foreach ($assets as $a) if ($a['status']==='active'): ?><option value="<?= e($a['id']) ?>"><?= e($a['name']) ?></option><?php endif; ?></select></label><button class="secondary">Add goal</button></form></section></div>
